import os
from dotenv import load_dotenv
from azure.storage.blob import BlobServiceClient


class AzureConfig:
    """Configuration class for connecting to Azure Blob Storage."""

    def __init__(self):
        load_dotenv()
        self.connection_string = os.getenv("AZURE_STORAGE_CONNECTION_STRING")
        self.container_name = os.getenv("AZURE_CONTAINER_NAME")
        self._blob_service_client = None
        self._container_client = None

        if not self.connection_string:
            raise ValueError("AZURE_STORAGE_CONNECTION_STRING is not set in environment variables")
        if not self.container_name:
            raise ValueError("AZURE_CONTAINER_NAME is not set in environment variables")

    @property
    def blob_service_client(self):
        """Initialize and return the Azure BlobServiceClient."""
        if not self._blob_service_client:
            self._blob_service_client = BlobServiceClient.from_connection_string(
                self.connection_string
            )
        return self._blob_service_client

    @property
    def container_client(self):
        """Return the client for an existing container."""
        if not self._container_client:
            self._container_client = self.blob_service_client.get_container_client(
                self.container_name
            )
        return self._container_client


# Singleton-style shared config instance
azure_config = AzureConfig()

from fastapi import APIRouter, UploadFile, File, HTTPException
from app.service import StorageService

router = APIRouter(prefix="/storage", tags=["Azure Blob Storage"])
service = StorageService()


@router.post("/files")
async def upload_file(file: UploadFile = File(...)):
    """Upload a file to Azure Blob Storage."""
    try:
        filename = service.upload_file(file)
        return {"message": f"File '{filename}' successfully uploaded to Azure Blob Storage."}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/files")
async def list_files():
    """Return a list of all files in the container."""
    try:
        return {"files": service.list_files()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/files/{filename}")
async def download_file(filename: str):
    """Read and return the content of a file."""
    try:
        content = service.download_file(filename)
        return {"filename": filename, "content": content}
    except FileNotFoundError as e:
        raise HTTPException(status_code=404, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.delete("/files/{filename}")
async def delete_file(filename: str):
    """Delete a file from Azure Blob Storage."""
    try:
        service.delete_file(filename)
        return {"message": f"File '{filename}' successfully deleted from Azure Blob Storage."}
    except FileNotFoundError as e:
        raise HTTPException(status_code=404, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

from azure.core.exceptions import ResourceNotFoundError
from .config import azure_config


class StorageService:
    """Business logic for working with Azure Blob Storage."""

    def __init__(self):
        self.container_client = azure_config.container_client

    def upload_file(self, file):
        """Upload file to Azure container."""
        blob_client = self.container_client.get_blob_client(file.filename)
        blob_client.upload_blob(file.file, overwrite=True)
        return file.filename

    def list_files(self):
        """List all blobs in the container."""
        return [blob.name for blob in self.container_client.list_blobs()]

    def download_file(self, filename: str) -> str:
        """Download the content of a file by name."""
        blob_client = self.container_client.get_blob_client(filename)
        try:
            stream = blob_client.download_blob()
            return stream.readall().decode("utf-8", errors="ignore")
        except ResourceNotFoundError:
            raise FileNotFoundError(f"File '{filename}' not found")

    def delete_file(self, filename: str):
        """Delete a file from the container."""
        blob_client = self.container_client.get_blob_client(filename)
        try:
            blob_client.delete_blob()
        except ResourceNotFoundError:
            raise FileNotFoundError(f"File '{filename}' not found")

from fastapi import FastAPI

app = FastAPI()


@app.get("/")
async def root():
    return {"message": "Hello World"}


@app.get("/hello/{name}")
async def say_hello(name: str):
    return {"message": f"Hello {name}"}

from fastapi import FastAPI
from app.routes.storage import router as storage_router

app = FastAPI()

# Include Azure Blob Storage routes
app.include_router(storage_router)


@app.get("/")
async def root():
    return {"message": "Hello World"}


@app.get("/hello/{name}")
async def say_hello(name: str):
    return {"message": f"Hello {name}"}
